<?php $page=max(1,min(100000,(int)($_GET['page']??1)));$status=in_array($_GET['status']??'',['pending','approved','rejected'],true)?$_GET['status']:'pending';$total=(int)$a->db->value('SELECT COUNT(*) FROM cy_reviews WHERE status=?',[$status]);$rows=$a->db->all('SELECT r.*,c.title,u.display_name,o.status AS order_status FROM cy_reviews r JOIN cy_contents c ON c.id=r.content_id JOIN cy_users u ON u.id=r.user_id JOIN cy_orders o ON o.id=r.order_id WHERE r.status=? ORDER BY r.id DESC LIMIT 30 OFFSET ?',[$status,($page-1)*30]); ?>
<div class="admin-title"><div><span class="eyebrow">COMMERCE / HONEST EXPERIENCES</span><h1><?= t('Product reviews') ?></h1><p><?= t('Only verified purchases qualify. Refunded purchases disappear from public ratings automatically.') ?></p></div></div>
<div class="filters section"><?php foreach(['pending','approved','rejected'] as $value): ?><a class="filter <?= $status===$value?'active':'' ?>" href="<?= e(au('reviews',['status'=>$value])) ?>"><?= t($value) ?></a><?php endforeach ?></div>
<section class="panel"><?php foreach($rows as $row): ?><article class="review-item"><header><div class="grow"><strong><?= e($row['display_name']) ?> / <?= e($row['title']) ?></strong><p class="hint"><?= t('Order') ?> #<?= (int)$row['order_id'] ?> &middot; <?= t($row['order_status']) ?></p></div><span class="rating-stars"><?= (int)$row['rating'] ?> / 5</span></header><p><?= nl2br(e($row['body'])) ?></p><div class="row"><?php foreach(['approved'=>'Approve','rejected'=>'Reject'] as $value=>$label): ?><?= form_start('admin_review') . hidden('id',$row['id']) . hidden('status',$value) ?><?php button($label,'secondary small'); ?></form><?php endforeach ?></div></article><?php endforeach ?><?php if(!$rows){empty_state();}partial('pagination',['tab'=>'reviews','pagination'=>['page'=>$page,'pages'=>max(1,(int)ceil($total/30))]]); ?></section>
